#!/usr/bin/env python3
"""sen0414_lineage_exam_leak v1_0_0 - records (ONE new register file) the coordinator's urgent instruction of 2026-11-02 (exam papers, keys and item sets with answers are in a PUBLIC repository): the story ST4_Leak (guard now, impact analysis, then the Owner's decision) and, after it, the repair story ST4_Rule5 (answer-sheet rule 5 text cut at the right edge; new file, own renderer copy, no edit to the SEN0401 module), both Ready in box 3, ranked 1 and 2, open scores re-run.
Usage: sen0414_lineage_exam_leak_v1_0_0.py"""
__version__ = "1.0.0"
import os, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import sen0414_lineage_standard_v1_2_0 as W
def blk(t, name):
    i = t.index("\nex:%s a backlog:" % name) + 1; j = t.find("\nex:", i + 1)
    return i, (len(t) if j < 0 else j)
IMPACT = ("IMPACT ANALYSIS of the lineage agent (2026-11-02, from the repository at commit c259fd5; the repository altunelyusuf/AdvancedProgrammingWithPython is PUBLIC, 0 forks, 0 stars at the time of the check; nothing was deleted or rewritten). "
 "(1) Files with ANSWERS or the means to rebuild the papers: 04-assessment/exams/items/ - items_a_v2_0_0, items_a_v2_1_0 and items_b_v2_0_0, each as paper list, make-up list and provisional side file (the 22-field records carry the field 'answer', options, listings and the chapters), plus their builders and checks (16 files); 04-assessment/exams/papers_r14/ - midterm forms A and B and make-up form A as paper and KEY .docx, two answer-sheet PDFs and layouts, and midterm_build.json and makeup_build.json (seed 20261102 and the pool ids; with the committed engine and the item lists anyone can rebuild every paper and key) (15 files). "
 "(2) Files that expose the design but not answers: exam_design_v1_2_0.json (structure, chapter weights, points), exam_engine_v1_0_0 and v1_1_0 with fixtures (synthetic), the critical-points lists of chapters 1 to 8 (course content that the items draw on; they name what is examined), the cover renderer, the .docx renderer and its check, the briefs r2 to r14 and the control logs (they describe the papers; a log of 2026-11-02 prints no key). "
 "(3) Commits that introduced answer-bearing files: 94e08e1 (2026-11-01, item set A 2.0.0), 034c4dd (2026-11-01, item set B 2.0.0), 275e1d9 (2026-11-02, item set A 2.1.0), e7d7821 (2026-11-02, papers and keys); the design and engine commits 097a253, bc305be, 1cc2daf, 540b51b and the critical points 30ba118, 0ff08fb, 3ecf1d4 expose structure and topics only. All are in the history of the default branch; 702 commits in all. "
 "(4) Reach: any visitor can read the files and the full history, clones and forks keep their own copies, and web caches or search indexes may hold them; hiding the files in a later commit does not remove them from the history, and rewriting history does not recall copies already taken. "
 "(5) What the papers already pushed are worth: the midterm of 2026-11 is built from them (seed 20261102), so the committed forms A and B and make-up form A are the actual papers if the Owner uses them; the item lists are provisional and would anyway need the Owner's review. "
 "(6) Options for the Owner's one question: (a) make the repository private now (stops further reading at once; the history stays but is private; the course pages published from it would need another home if they are served from this repository); (b) move the exam material to a private repository and rewrite the history of this one to remove it (removes it from the history after a force push; copies already taken stay; needs the Owner's explicit decision, a backup and re-clone by every user); (c) accept the exposure (and change the papers: build new ones from new items with a new seed, kept outside the public repository). The agent recommends (a) at once, then (b) or (c) once the Owner has decided how to use these papers. "
 "(7) What was done without waiting: new exam answer data is NOT committed from now on (the .gitignore guard of 2026-11-02 ignores new papers_*/ folders, new item-set versions, keys, builds and sheets; files already tracked stay tracked); the line in the executor briefs that exam artefacts stay local and untracked or go where the Owner names is part of the guard task TK4_Leak_Guard and is relayed to executors by the coordinator until then.")
RULE = ("Task text: the answer sheet is rendered by the SEN0401 sheet module, which cannot be edited from SEN0414; rule 5 of the sheet's instructions is cut off at the right edge (seen on the rendered midterm_answersheet.pdf and makeup_answersheet.pdf by the lineage agent, 2026-11-02). Deliverable: a NEW file in 04-assessment/exams that holds SEN0414's own copy of the renderer's instruction block (or a wrapper that sets the line breaks) so that every instruction line, rule 5 included, fits inside the sheet's margins; the sheet stays one page with 31 units; the committed v1.0.0 renderer, the SEN0401 module and the committed sheets are not edited; the .docx renderer is wired to the new file only in a new renderer version. Control: render the sheet, extract the text with its coordinates and prove that no instruction glyph lies right of the margin; the check of the position of the answer boxes is unchanged. Not committed to the public repository: the rebuilt sheets are kept local (ST4_Leak). Estimated 0.3 hours (an estimate, G120).")
def main():
    src = W.newest(); t = open(src, encoding="utf-8").read(); now = W.now(); nowZ = now + "Z"; add = []
    stories = {
     "ST4_Leak": ("Keep exam answers out of the public repository", "Cat_Compliance", ["TK4_Leak_Guard", "TK4_Leak_Guard_Verify"], 0.5, (20, 25, 25), "the exam papers, keys and item sets with answers are not published before the exam", "students cannot read the papers or the answers before the sitting, and the Owner decides what happens to what was already pushed",
       {"TK4_Leak_Guard": ("Guard: no new exam answer data enters the public repository", "Build", "Deliverable: the ignore rules in .gitignore for new exam folders, item-set versions, keys, builds and sheets (written 2026-11-02, new patterns only; tracked files stay tracked), the executor-brief line that exam artefacts stay local and untracked, and the impact analysis recorded on this story. The rewrite or removal of what is already pushed is NOT part of this task: it waits for the Owner's decision and then becomes a new task. Estimated 0.5 hours (an estimate, G120)."),
        "TK4_Leak_Guard_Verify": ("Verify the guard", "Verify", "Control by the lineage agent: git check-ignore names each pattern for a sample new path (papers folder, item set version, key, build, sheet); git status shows no untracked exam answer file as addable; the pushed files and history are unchanged (nothing deleted, no rewrite); the impact analysis lists the files and commits found by git. Estimated 0.2 hours (an estimate, G120).")}),
     "ST4_Rule5": ("Answer sheet: rule 5 fits inside the margin", "Cat_Compliance", ["TK4_Rule5", "TK4_Rule5_Verify"], 0.3, (5, 5, 5), "the answer sheet's rule 5 text is complete and inside the margin", "a student can read every rule of the printed answer sheet",
       {"TK4_Rule5": ("Rule 5 of the answer sheet inside the margin (new file, SEN0414's own renderer copy)", "Build", RULE),
        "TK4_Rule5_Verify": ("Verify the answer sheet instruction block", "Verify", "Control by the lineage agent: renders the sheet, extracts the text with coordinates, proves no instruction glyph right of the margin, one page, 31 units, the answer boxes unmoved, no committed file or SEN0401 file edited. Estimated 0.2 hours (an estimate, G120).")})}
    order = ("ST4_Leak", "ST4_Rule5")
    for sid in order:
        title, cat, tasks, size, (bv, tc, rr), want, sothat, tdefs = stories[sid]
        val = (bv + tc + rr) / size
        add.append('\nex:%s a backlog:Story ; rdfs:label %s@en ; backlog:hasIdentifier "%s" ; backlog:hasTitle %s ;\n    backlog:belongsToLineage ex:Lineage4 ; backlog:memberOfContainer ex:Iter_Ex3 ; backlog:responsible ex:Executor_ClaudeCodeSession ; backlog:admittedByOutput ex:Out4_Backlog ;\n    backlog:hasInvestmentCategory backlog:%s ;\n    backlog:asRole "SEN0414 instructor" ; backlog:wantsCapability %s ; backlog:soThat %s ;\n    backlog:satisfiesDeliverable ex:Del4_Papers ; backlog:pursuesObjective ex:Obj4_PapersBuilt ; backlog:hasAcceptanceCriterion ex:AC4_Controlled ;\n    backlog:coversEntity ex:DE4_ExamPaper ; backlog:coversStage backlog:Stage_Creation ;\n    backlog:effectiveDefinitionOfDone ex:DoD ; backlog:hasApplicableConcern backlog:Concern_Data ;\n    backlog:decomposesInto %s ;\n    backlog:hasState backlog:Ready ; backlog:hasPriorityScore ex:Score5a_%s ;\n    backlog:hasAuditNote %s .\n' % (sid, W.lit(title), sid, W.lit(title), cat, W.lit(want), W.lit(sothat), ", ".join("ex:" + k for k in tasks), sid,
              W.lit(("COORDINATOR INSTRUCTION of 2026-11-02, recorded as relayed (not an Owner decision; an urgent interruption of the lineage can only be declared by the Owner, so none is declared): treat the exposure of exam material in the public repository as urgent, commit no further exam keys, answer data or final papers to it, and open an urgent item with re-ranking and an impact analysis; do not rewrite history or delete anything without the Owner's decision. " + IMPACT) if sid == "ST4_Leak" else "COORDINATOR INSTRUCTION of 2026-11-02, recorded as relayed: register the small repair task for the cut-off rule 5 on the answer sheet (new file, own renderer copy, no edit to the SEN0401 module), re-ranked, after the exposure item ST4_Leak. Found by the lineage agent when controlling TK4_Papers.")))
        add.append('ex:Score5a_%s a backlog:PriorityScore ; backlog:scoredByMethod backlog:Method_WSJF ;\n    backlog:hasScoreValue "%.2f"^^xsd:decimal ; backlog:scoredAt "%sZ"^^xsd:dateTime ; backlog:isAveragedFromMembers false ;\n    backlog:hasScoreRationale %s .\n' % (sid, val, now, W.lit("WSJF = (business value %d + time criticality %d + risk reduction %d) / job size %.1f h = %.2f. First scoring %s UTC; %s" % (bv, tc, rr, size, val, now, "the exam material is readable by anyone now and the sitting is near: highest value and criticality." if sid == "ST4_Leak" else "a sheet defect that does not block the sitting."))))
        for k in tasks:
            ttitle, typ, text_ = tdefs[k]; isv = typ == "Verify"
            add.append('\nex:%s a backlog:ExecutionTask ; rdfs:label %s@en ; backlog:hasIdentifier "%s" ; backlog:hasTitle %s ;\n    backlog:belongsToLineage ex:Lineage4 ; backlog:memberOfContainer ex:Iter_Ex3 ; backlog:admittedByOutput ex:Out4_Backlog ; backlog:responsible ex:Executor_ClaudeCodeSession ;\n    backlog:hasInvestmentCategory backlog:%s ; backlog:hasTaskType backlog:TaskType_%s ; backlog:effectiveDefinitionOfDone ex:DoD ; backlog:hasState backlog:Ready ;\n%s    backlog:notYetScoreable true ; backlog:hasScoreabilityReason "Ranked by its story\'s state; scoring both would double-count." ;\n    backlog:hasAuditNote %s .\n' % (k, W.lit(ttitle), k, W.lit(ttitle), "Cat_Compliance" if isv else cat, typ, "    backlog:dependsOn ex:%s ;\n" % tasks[0] if isv else "", W.lit(text_)))
        for k in [sid] + tasks:
            add.append('ex:Refine5a_%s a backlog:RefinementEvent ; rdfs:label "Refinement that made %s ready"@en ;\n    backlog:refines ex:%s ; backlog:addressesConcern backlog:Concern_Data ; backlog:refinedAt "%s"^^xsd:dateTime ;\n    backlog:refinedBy backlog:Builder ; backlog:groomsForIteration ex:Iter_Ex3 ; backlog:hasWorkKind backlog:WorkKind_Preparation ;\n    backlog:hasRefinementOutcome "Refined from the coordinator\'s instruction of 2026-11-02: deliverable, check and estimate are written in the item." .\n' % (k, k, k, now))
            add.append('ex:RC5a_%s a backlog:ReadinessCheck ; rdfs:label "Readiness check of %s"@en ; backlog:checksReadinessOf ex:%s ; backlog:readinessCheckedAt "%s"^^xsd:dateTime ;\n    backlog:hasReadinessCriterion ex:RK5a_%s_1, ex:RK5a_%s_2, ex:RK5a_%s_3 .\n' % (k, k, k, now, k, k, k))
            for kx, tx in ((1, "The deliverable, its place and its check are written in the item."), (2, "Every dependency of the item is Done or a task of the same story that precedes it."), (3, "The statements that bound the item are recorded on the story.")):
                add.append('ex:RK5a_%s_%d a backlog:ReadinessCriterion ; rdfs:label %s@en ; backlog:criterionMet true .\n' % (k, kx, W.lit(tx)))
            add.append('ex:Mv5a_%s a backlog:TransitionEvent ; rdfs:label %s@en ; backlog:transitionedItem ex:%s ;\n    backlog:viaTransition backlog:T_Refine ; backlog:transitionedAt "%s"^^xsd:dateTime ; backlog:transitionedBy backlog:Builder ;\n    backlog:hasTransitionNote %s .\n' % (k, W.lit(k + " moved to Ready"), k, nowZ, W.lit("Refined (ex:Refine5a_%s) and ready after the readiness check ex:RC5a_%s; no executor has started." % (k, k))))
        add.append('ex:Plan5a_%s a backlog:PlanningEvent ; rdfs:label "Planning of %s into box 3"@en ; backlog:belongsToLineage ex:Lineage4 ;\n    backlog:plannedAt "%s"^^xsd:dateTime ; backlog:plannedBy backlog:Builder ; backlog:plannedInto ex:Iter_Ex3 ;\n    backlog:plansItem ex:%s ; backlog:producesTask %s ;\n    backlog:refinementProduces ex:Spec4, ex:Scen4_Sound, ex:Scen4_Refused .\n' % (sid, sid, now, sid, ", ".join("ex:" + k for k in tasks)))
        add.append("ex:Iter_Ex3 backlog:hasMember ex:%s, %s .\nex:EP4_Engine backlog:decomposesInto ex:%s .\nex:Obj4_PapersBuilt backlog:metricMovableBy ex:%s .\n" % (sid, ", ".join("ex:" + k for k in tasks), sid, sid))
    add.append("ex:TK4_Rule5 backlog:dependsOn ex:TK4_Leak_Guard_Verify .\n")
    done_loop = []
    for s2 in sorted(set(re.findall(r"\nex:(ST\w*?_\w+) a backlog:Story", t))):
        i, j = blk(t, s2); b = t[i:j]
        m = re.search(r"backlog:hasPriorityScore ex:Score(\d+[a-z]?)_%s\b" % s2, b)
        if not m or "backlog:hasState backlog:Done" in b or "backlog:hasState backlog:Cancelled" in b: continue
        kk = m.group(1)
        if ("\nex:Score%s_%s a" % (kk, s2)) not in t: continue
        k0 = t.index("\nex:Score%s_%s a" % (kk, s2)) + 1; r0 = t[k0:t.find("\nex:", k0 + 1)]
        q = re.search(r"business value (\d+) \+ time criticality (\d+) \+ risk reduction (\d+)\) / job size ([\d.]+) h", r0)
        if not q: continue
        nk = (kk[:-1] + chr(ord(kk[-1]) + 1)) if kk[-1].isalpha() else str(int(kk) + 1); nid = "Score%s_%s" % (nk, s2)
        if ("ex:" + nid + " a ") in t: continue
        bv, tc, rrr, size_ = int(q.group(1)), int(q.group(2)), int(q.group(3)), float(q.group(4)); val = (bv + tc + rrr) / size_
        t = t[:i] + b.replace(m.group(0), "backlog:hasPriorityScore ex:" + nid, 1) + t[j:]
        add.append('ex:%s a backlog:PriorityScore ; backlog:scoredByMethod backlog:Method_WSJF ;\n    backlog:hasScoreValue "%.2f"^^xsd:decimal ; backlog:scoredAt "%sZ"^^xsd:dateTime ; backlog:isAveragedFromMembers false ;\n    backlog:hasScoreRationale %s .\n' % (nid, val, now, W.lit("WSJF = (business value %d + time criticality %d + risk reduction %d) / job size %.1f h = %.2f. RE-RUN on %s UTC after the repairs ST4_Leak and ST4_Rule5 entered the backlog and rank above it. Inputs unchanged." % (bv, tc, rrr, size_, val, now))))
        done_loop.append(s2)
    add.append("ex:Lineage4 backlog:hasAuditNote %s .\n" % W.lit("RANKING %s UTC after the exposure item and the sheet repair entered (the coordinator's instruction of 2026-11-02): 1 ST4_Leak (guard now; the Owner's decision on what is already pushed follows and becomes a task then), 2 ST4_Rule5 (local build only), then the rest as before; open scores re-run: %s. No urgent interruption is declared: only the Owner can declare one." % (now, ", ".join(done_loop) or "none")))
    out = W.write_new(src, t + "\n" + "".join(add), "Exam change: urgent exposure item ST4_Leak (guard and impact analysis; no history rewrite without the Owner) and repair ST4_Rule5 Ready and ranked 1 and 2, scores re-run.")
    print(os.path.basename(out))
main()
